import DOMPurify from "dompurify";

// A remote subresource in model output is an outbound request nobody approved,
// so the renderer drops every tag that can fetch one.
export function safeHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    FORBID_TAGS: ["img", "picture", "source", "video", "iframe", "link"],
  });
}
